settings.css:
body{background-color:rgba(0,0,0,0);margin:0;overflow:hidden} /* Chat des lives Latshow, gaming et montage (page dock.html de Social Stream Ninja, CSS posé dans la source OBS par
   obs/generer.mjs). Demande du client, 2026-10-09 : « un chat clean avec la bonne typo », 14 px. Habillage « papa »
   (2026-11-08) : Bricolage Grotesque, pseudo ambre, texte crème, sur le panneau brun que dessine la page de la scène ;
   petit logo de la plateforme ; ni bande, ni contour, ni menu. La source a la taille exacte de son cadre. */
@import url('https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:opsz,wght@14,400;14,700&display=swap');
#menu,#context-menu{display:none!important}
html,body,#output{background:transparent!important}
/* La page décale la liste de 32 px vers la gauche (ascenseur caché) : rognait les logos et les lignes. */
#output{left:0!important;right:0!important;width:auto!important;box-sizing:border-box!important;padding:0 14px 12px!important}
.highlight-chat{background:transparent!important;border:0!important;box-shadow:none!important;padding:3px 0!important;margin:0!important}
.hl-message{display:block!important;font:400 14px/1.4 'Bricolage Grotesque',sans-serif!important;color:#FFF3E3!important;text-shadow:none!important;-webkit-text-stroke:0!important;letter-spacing:0!important;text-indent:0!important;padding:0!important;margin:0!important;overflow:visible!important}
.hl-source-type{width:12px!important;height:12px!important;vertical-align:-2px!important;margin:0 6px 0 0!important;opacity:.85}
.hl-name{display:inline!important;font:700 14px/1.4 'Bricolage Grotesque',sans-serif!important;color:#F4A33A!important;margin-right:6px!important;text-shadow:none!important;-webkit-text-stroke:0!important}
.hl-content{display:inline!important;font:400 14px/1.4 'Bricolage Grotesque',sans-serif!important;color:#FFF3E3!important;text-shadow:none!important;-webkit-text-stroke:0!important}

